create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, household_name text not null default 'My household', created_at timestamptz not null default now());
create table public.staff (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null check(length(trim(name))>0), phone text, joining_date date not null default current_date, notes text not null default '', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.services (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, name text not null, category text not null default 'custom', monthly_base numeric(12,2) not null default 0 check(monthly_base>=0), deduction_rate numeric(12,4) not null default 0 check(deduction_rate>=0), deduction_unit text not null default 'day', active boolean not null default true, created_at timestamptz not null default now(), unique(user_id,name));
create table public.staff_services (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, service_id uuid not null references public.services(id) on delete cascade, created_at timestamptz not null default now(), unique(staff_id,service_id));
create table public.attendance (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, service_id uuid not null references public.services(id) on delete cascade, attendance_date date not null, status text not null check(status in ('completed','absent','partial','weekly_off','special_holiday')), tasks jsonb not null default '{}', notes text not null default '', correction_reason text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(staff_id,service_id,attendance_date));
create table public.leaves (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, leave_date date not null, leave_type text not null check(leave_type in ('paid','unpaid','weekly_off','special_holiday')), notes text not null default '', created_at timestamptz not null default now(), unique(staff_id,leave_date));
create table public.holidays (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, holiday_date date not null, name text not null, holiday_type text not null check(holiday_type in ('weekly_off','special','working_day')), paid boolean not null default true, created_at timestamptz not null default now(), unique(user_id,holiday_date));
create table public.salary_settings (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid references public.staff(id) on delete cascade, paid_holidays_per_month integer not null default 2 check(paid_holidays_per_month>=0), cleaning_divisor numeric(8,2) not null default 30 check(cleaning_divisor>0), updated_at timestamptz not null default now());
create table public.monthly_salary (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, salary_month date not null, version integer not null default 1 check(version>0), status text not null default 'draft' check(status in ('draft','finalized')), calculation jsonb not null default '{}', base_total numeric(12,2) not null default 0, deductions numeric(12,2) not null default 0, additions numeric(12,2) not null default 0, advances numeric(12,2) not null default 0, payable numeric(12,2) not null default 0 check(payable>=0), finalized_at timestamptz, created_at timestamptz not null default now(), unique(staff_id,salary_month,version));
create table public.salary_adjustments (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, adjustment_date date not null default current_date, category text not null check(category in ('advance','bonus','other')), amount numeric(12,2) not null check(amount>0), description text not null default '', created_at timestamptz not null default now());
create table public.extra_work (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, task_name text not null, description text not null default '', work_date date not null default current_date, amount numeric(12,2) not null check(amount>=0), status text not null default 'pending' check(status in ('pending','completed','approved')), notes text not null default '', created_at timestamptz not null default now());
create table public.payments (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid not null references public.staff(id) on delete cascade, salary_month date not null, amount numeric(12,2) not null check(amount>0), payment_date date not null default current_date, method text not null default 'Cash', notes text not null default '', created_at timestamptz not null default now());
create table public.activity_logs (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, staff_id uuid references public.staff(id) on delete set null, entity_type text not null, action text not null, details jsonb not null default '{}', created_at timestamptz not null default now());
create index on public.staff(user_id,active); create index on public.attendance(user_id,attendance_date); create index on public.attendance(staff_id,attendance_date); create index on public.leaves(user_id,leave_date); create index on public.monthly_salary(user_id,salary_month); create index on public.salary_adjustments(staff_id,adjustment_date); create index on public.extra_work(staff_id,work_date); create index on public.payments(staff_id,salary_month);
do $$ declare t text; begin foreach t in array array['staff','services','staff_services','attendance','leaves','holidays','salary_settings','monthly_salary','salary_adjustments','extra_work','payments','activity_logs'] loop execute format('alter table public.%I enable row level security',t); execute format('create policy household_isolation on public.%I for all using (user_id = auth.uid()) with check (user_id = auth.uid())',t); end loop; end $$;
alter table public.profiles enable row level security;
create policy profile_self on public.profiles for all using (id=auth.uid()) with check (id=auth.uid());
create or replace function public.bootstrap_profile() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,household_name) values(new.id,coalesce(new.raw_user_meta_data->>'household_name','My household')) on conflict(id) do nothing; insert into public.services(user_id,name,category,monthly_base,deduction_rate,deduction_unit) values (new.id,'Cooking','cooking',4500,50,'missed_meal'),(new.id,'Dusting & cleaning','cleaning',500,500.0/30,'absence_day') on conflict(user_id,name) do nothing; insert into public.salary_settings(user_id,paid_holidays_per_month,cleaning_divisor) values(new.id,2,30); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.bootstrap_profile();
